mapper.select:
SELECT m.member_id, COALESCE(g.current_grade, 0) AS grade_code
FROM t_member m
LEFT JOIN t_member_growth g ON g.member_id = m.member_id
WHERE m.member_id > #{afterMemberId}
AND COALESCE(g.current_grade, 0) >= #{minGrade}

    AND m.birthday IS NOT NULL
    AND (
    (MONTH(m.birthday) = #{birthMonth} AND DAY(m.birthday) = #{birthDay})


        OR (MONTH(m.birthday) = 2 AND DAY(m.birthday) = 29)

    )

ORDER BY m.member_id
LIMIT #{limit}

mapper.update:
UPDATE t_grade_entitlement_grant
SET status = 2
WHERE status = 0
AND expire_time <= #{now}
LIMIT #{limit}

UPDATE t_grade_entitlement_grant
SET status = 1, claim_time = #{now}
WHERE id = #{id}
AND member_id = #{memberId}
AND status = 0
AND expire_time > #{now}

UPDATE t_grade_entitlement_grant
SET grant_result = #{result}
WHERE id = #{id}
